/**
 * Parses Nominatim geocoding JSON response and extracts the first result's latitude and longitude.
 * @param {string} geocodingJson - JSON response from Nominatim geocoding
 * @returns {Promise.<string>}
 */
export async function JSA_Geocoding_ParseResult(geocodingJson) {
	// BEGIN USER CODE
    if (!geocodingJson) return "0,0";
    try {
        const data = JSON.parse(geocodingJson);
        if (!Array.isArray(data) || data.length === 0) {
            return "0,0";
        }
        const first = data[0];
        return parseFloat(first.lat) + "," + parseFloat(first.lon);
    } catch (e) {
        return "0,0";
    }
	// END USER CODE
}
